## tl;dr


```ts
// Backend:
const appRouter = router({
  hello: publicProcedure
    .query(async () => {
      return new Response('Hello World');
    }),
});

export type AppRouter = typeof appRouter;

// Usage:
const client = createTRPCClient<AppRouter>({
  links: [
    httpLink({
      url: '/api',
    }),
  ],
});


const res = await client.hello.query();
//     ^? Response
```



